    ("佈署", "部署"),
    ("運載工具", "載具"),
    ("小對", "小隊"),
    ("當面對強大的敵人時，總是適著尋找側面攻擊的路徑將是最有效的方式。", "面對強大的敵方陣地時，務必尋找可用於側翼攻擊的路線。"),
    ("於技能啟動的時間內治療於周圍的步兵，並能復活倒下的指揮官。", "技能啟動期間治療藥劑師周圍的友方步兵，並可復活倒下的指揮官。"),
    ("部署導彈來擊穿越裝甲。", "發射導彈擊穿裝甲。"),
    ("選定塔庫斯小隊，並啟動反白手榴彈技能（左鍵點擊）並點擊目標區域。", "選定塔庫斯小隊，啟動高亮顯示的手榴彈技能（左鍵點擊），然後指定高亮顯示的目標區域。"),
    ("給予掘蟒蟲首領近戰攻擊帶有酸液濺撒的效果，可以損害附近的部隊。", "使掘蟒蟲首領的近戰攻擊附帶酸液濺射效果，對附近單位造成傷害。"),
    ("我使靈族步行機甲手上受損害的傷口癒合了，指揮官。", "我已經治好了靈族步行機甲造成的傷口，指揮官。"),
    ("你的小隊恢復了，並準備好攻擊受傷的野獸。", "你的小隊已經恢復，準備好攻擊那頭受傷的野獸。"),
    ("指揮官，你的小隊恢復了，並準備好再次展開部署。", "指揮官，你的小隊已經恢復，準備好再次部署。"),
    ("我們最後的靈能通訊員努力把這訊息傳給你時受到了損害，只有一些智庫學者和領航員留下來領導我們。", "我們最後一名星語者在努力向你傳送這則訊息時正承受巨大痛苦，只剩少數智庫與領航員仍能引導我們。"),
    ("當我們集中火力時，我們的重型爆彈槍可以打破掩護甚至擊倒燈火載具。", "集中火力時，我們的重型爆彈槍可以擊穿掩體，甚至摧毀輕型載具。"),
    ("載具是比步兵隊更好的裝甲部隊。他們可以不理爆彈槍。", "載具的裝甲遠勝步兵，可以無視爆彈槍火力。"),
    ("熱熔彈是設計好穿越載具裝甲燃燒的。把一個拿到那載具上。", "熱熔炸彈就是為燒穿載具裝甲而設計的。把一枚送到那輛載具上。"),
    ("導彈發射器是有效的反載具武器。拿一個到載具上。", "導彈發射器是有效的反載具武器。用它攻擊那輛載具。"),
    ("等離子槍可以穿過那個載具裝甲。", "等離子槍可以擊穿那輛載具的裝甲。"),
    ("對我我們部署對危難信號的反應來說，這讓它更困難了。", "這會讓我們更難針對求救信號部署部隊。"),
    ("軍士是擁有近戰能力的戰士。他們被賦予無畏無懼的能力可造成損害並免除被敵人壓制，但會降低移動的速度。", "軍士是具備近戰能力的戰士。他們賦予小隊「無所畏懼」能力，提高遠程傷害並免疫壓制，但會降低移動速度。"),
    ("殺死這靈能蟲將導致蟲巢意志受到損害與蟲巢艦隊退卻。", "殺死這隻靈能蟲將重創蟲巢意志，迫使蟲巢艦隊撤退。"),
    ("星球防禦現在處於高度警戒，而修護工作人員已經被派往去處理已經造成的損害。", "星球防禦現已進入高度警戒，維修隊也已派出處理既有損害。"),
    ("蟲巢意志企圖侵擾更多區域，而這頭野獸很有可能正試圖形成一個新蟲巢。擊倒此異形，蟲巢意志將會受到損害。", "蟲巢意志正試圖侵染更多區域，這頭野獸很可能正在形成新的蟲巢。擊倒這隻蟲巢暴君，蟲巢意志將遭受重創。"),
    ("軌道內部隊可免於遠程攻撃損害，但無法持續使用遠程武器。", "球體內的部隊免疫遠程傷害，但在效果持續期間無法使用自己的遠程武器。"),
    ("大幅提升速度，但持續損害力降低。", "大幅提升速度，但在持續期間降低傷害。"),
    ("給予小隊短暫的無敵效果增加損害能力並免於壓制。", "使小隊短時間無敵，提升造成的傷害，並免疫壓制。"),
    ("孢子爆炸後將會產生有毒氣體，可使附近部隊昏迷並有輕微損害。", "孢子地雷會立刻爆炸成一團毒氣，震暈附近單位，但只造成少量傷害。"),
