    ("異族入侵正以可怕速度在地下城蔓延。它們現在威脅要淹沒梅里迪安的主要太空港。", "異族入侵正以驚人速度在下層城巢蔓延。它們現在威脅要淹沒梅里迪安的主要太空港。"),
