    ("Never forget. Never forgive.", "永不遺忘。永不寬恕。"),
    ("I shall fight on.", "我將繼續戰鬥。"),
    ("Damnation.", "該受詛咒。"),
    ("Secure the perimeter, brother.", "確保周邊安全，兄弟。"),
    ("Eyes open. One moment of laxity may damn us all.", "保持警惕。一瞬鬆懈就可能讓我們全體萬劫不復。"),
    ("We shall be remembered in the Book of Honor.", "我們將被銘記於榮譽之書。"),
    ("Stay at the ready.", "保持戒備。"),
    ("Brothers, tend to your weapons and equipment.", "兄弟們，整備你們的武器與裝備。"),
    ("Bless us as we go into combat in His name.", "願祂祝福我們以祂之名投入戰鬥。"),
    ("Remain at guard positions brothers.", "兄弟們，留在警戒位置。"),
    ("We have faced savage enemies before, brother, but every foe can be your last.", "我們曾面對野蠻的敵人，兄弟，但每一個敵人都可能成為你的終局。"),
    ("Vigilance, brothers. Always vigilance.", "警醒，兄弟們。永遠警醒。"),
    ("The fury of battle will come soon enough, brothers.", "戰鬥的狂怒很快就會降臨，兄弟們。"),
    ("We underestimate the aliens at our peril, brother. Though they are depraved and inhuman, the Eldar are deadly.", "低估異族會讓我們陷入危險，兄弟。靈族雖墮落且非人，卻十分致命。"),
    ("Keep in formation.", "保持隊形。"),
    ("Let those who once lived here be protected. Or avenged.", "願曾居於此者得到守護，或得到復仇。"),
    ("The mightiest weapon is powerless without the warrior to wield it.", "再強大的武器，若無戰士揮舞，也毫無力量。"),
    ("No activity.", "沒有活動跡象。"),
    ("Let none find us wanting. In His name.", "勿讓任何人見我們有所欠缺。以祂之名。"),
    ("Answer the enemy's quiet with vigilance, brother.", "以警醒回應敵人的沉默，兄弟。"),
    ("The Emperor Protects, but the Space Marine strikes.", "帝皇庇佑，而星際戰士出擊。"),
    ("Remember the Primarchs. They watch us still.", "銘記基因原體。他們仍在注視我們。"),
    ("Brothers, return fire!", "兄弟們，還擊！"),
    ("Stand firm.", "堅守陣地。"),
    ("Brothers, the Emperor protects.", "兄弟們，帝皇庇佑。"),
    ("Make them pay for this assault!", "讓他們為這次攻擊付出代價！"),
    ("No blow will go unanswered.", "每一擊都必將回應。"),
    ("Alien fiends!", "異族惡徒！"),
    ("The time is now, brothers.", "時候到了，兄弟們。"),
    ("Let none find us wanting.", "勿讓任何人見我們有所欠缺。"),
    ("My faith is my shield. My fury is my sword.", "信仰是我的盾，狂怒是我的劍。"),
    ("We will not bow before these attacks, brothers. We will not!", "我們不會在這些攻擊前屈膝，兄弟們。絕不！"),
    ("There is only the Emperor; he is our shield and protector.", "唯有帝皇；祂是我們的盾與守護者。"),
    ("A fine welcome for us, brothers. Return the greeting in kind.", "真是隆重的歡迎，兄弟們。以同樣方式回敬。"),
    ("They will regret this day.", "他們會為今日後悔。"),
    ("Come, show me what passes for fury among your misbegotten kind.", "來吧，讓我見識你們這些孽物所謂的狂怒。"),
    ("The enemy wishes to fight, brothers. Let us indulge them.", "敵人渴望戰鬥，兄弟們。滿足他們。"),
