    ("Lock on and return fire.", "鎖定並還擊。"),
    ("Alien witches. The Emperor protects.", "異族女巫。帝皇庇佑。"),
    ("Eldar vehicle. Let us show them our might.", "靈族載具。讓他們見識我們的威能。"),
    ("The Orks seek their death. Oblige them.", "獸人自尋死路。成全他們。"),
