    ("The Emperor provides weapons for his chosen.", "帝皇為祂的選民賜予武器。"),
    ("Stratagem under control, brother.", "戰略資產已受控制，兄弟。"),
    ("Strategic location marked.", "戰略位置已標記。"),
    ("Securing area.", "正在確保區域。"),
    ("This is Imperial territory now.", "此地現在是帝國領土。"),
    ("Damnation.", "該死。"),
    ("Secure the perimeter, brother.", "確保周界，兄弟。"),
    ("Eyes open. One moment of laxity may damn us all.", "睜大眼睛。片刻鬆懈就可能讓我們全都萬劫不復。"),
    ("We shall be remembered in the Book of Honor.", "我們將被銘記於榮譽之書。"),
    ("Stay at the ready.", "保持戒備。"),
    ("Brothers, tend to your weapons and equipment.", "兄弟們，照料你們的武器與裝備。"),
    ("Bless us as we go into combat in His name.", "當我們以祂之名投入戰鬥時，願祂祝福我們。"),
    ("Remain at guard positions brothers.", "留在警戒位置，兄弟們。"),
    ("We have faced savage enemies before, brother, but every foe can be your last.", "我們曾面對野蠻敵人，兄弟，但每一個敵人都可能是你的最後一個。"),
    ("Vigilance, brothers. Always vigilance.", "警惕，兄弟們。永遠警惕。"),
    ("The fury of battle will come soon enough, brothers.", "戰鬥的狂怒很快就會到來，兄弟們。"),
    ("We underestimate the aliens at our peril, brother. Though they are depraved and inhuman, the Eldar are deadly.", "兄弟，低估異族會讓我們自陷險境。靈族雖墮落且非人，卻十分致命。"),
    ("Let those who once lived here be protected. Or avenged.", "願曾居於此者得到守護。或得到復仇。"),
    ("The mightiest weapon is powerless without the warrior to wield it.", "最強大的武器若無戰士揮使，也毫無力量。"),
    ("No activity.", "沒有動靜。"),
    ("Let none find us wanting. In his name.", "勿讓任何人認為我們有所欠缺。以祂之名。"),
    ("Answer the enemy's quiet with vigilance, brother.", "以警惕回應敵人的寂靜，兄弟。"),
    ("The Emperor Protects, but the Space Marine strikes.", "帝皇庇佑，但星際戰士出擊。"),
    ("I die for my brothers and my Emperor.", "我為兄弟與帝皇而死。"),
    ("None found me wanting.", "無人能說我有所欠缺。"),
    ("Avenge me.", "為我復仇。"),
    ("Executing.", "正在執行。"),
