    ("Duty and Honor.", "職責與榮譽。"),
    ("Without hesitation.", "毫不猶豫。"),
    ("I shall not fail you, brother.", "我不會讓你失望，兄弟。"),
    ("Consider it done.", "就當已經完成。"),
