    ("I live through sacrifice.", "我以犧牲而活。"),
    ("I am the bloodied handed god", "我是血手之神"),
    ("None but me may judge the Eldar.", "唯有我能審判靈族。"),
    ("Your sacrilege will bring you eternal woe.", "你的褻瀆將帶來永恆悲禍。"),
