    ("The weather takes an ill turn.", "天候轉壞了。"),
    ("There may be fighting en route.", "途中可能會有戰鬥。"),
    ("This is no place for resting.", "這裡不是休息之地。"),
    ("I prefer to keep moving.", "我寧願保持移動。"),
    ("I go where there is need of me.", "我前往需要我的地方。"),
    ("I have found the place.", "我找到地方了。"),
    ("To stop is to succumb.", "停下就是屈服。"),
    ("Carefully.", "小心。"),
    ("The smallest shift can be significant.", "最微小的移動也可能意義重大。"),
    ("None will mark my passing.", "無人會察覺我經過。"),
    ("I am in position.", "我已就位。"),
    ("I may bring the battle with me.", "我可能把戰鬥帶來。"),
    ("I must lose my pursuers.", "我必須甩掉追兵。"),
    ("I shall not stand here to be pelted.", "我不會站在這裡挨打。"),
    ("I shall scout ahead.", "我會向前偵察。"),
    ("On my way.", "我在路上。"),
    ("I know my path.", "我知道我的道途。"),
    ("I forge ahead.", "我向前開路。"),
    ("A far better standpoint.", "遠更好的立足點。"),
    ("I will survey the route ahead.", "我會偵察前方路線。"),
    ("We have business elsewhere.", "我們在別處還有事。"),
    ("Keep moving, Rangers.", "繼續移動，遊俠。"),
    ("Do not allow the enemy to follow.", "不要讓敵人跟上。"),
    ("I see a refuge.", "我看見一處庇護所。"),
    ("Rangers, set forth.", "遊俠，出發。"),
    ("We must shift position.", "我們必須轉移位置。"),
    ("To a better vantage.", "去更好的制高點。"),
    ("The Rangers are underway.", "遊俠已在路上。"),
    ("Over there.", "在那邊。"),
    ("Remain under cloak throughout.", "全程保持隱蔽。"),
    ("Remove us -- quickly.", "帶我們離開，快。"),
    ("Convey us there.", "把我們送到那裡。"),
    ("Let us ride.", "讓我們乘行。"),
    ("A chasm extends before me, it is untraversable.", "一道裂谷在我面前延伸，無法通行。"),
    ("I have come up against a sheer drop.", "我遇到了一處峭壁。"),
    ("I cannot advance so long as this gate stands.", "只要這道門還在，我就無法前進。"),
    ("Only great force will bring that gate down.", "唯有強大力量才能擊倒那道門。"),
    ("I am cut off.", "我被切斷了。"),
    ("It seems the terrain has been misread.", "看來地形被誤判了。"),
    ("The bearing I was given is clearly incorrect.", "給我的方位顯然不正確。"),
    ("I must make some corrections to your map.", "我必須修正你的地圖。"),
    ("The wall prevents me.", "牆阻擋了我。"),
    ("A high wall rears up before me.", "一堵高牆矗立在我面前。"),
    ("Heavy fire encumbers me.", "重火力妨礙了我。"),
    ("The foe have me in check.", "敵人牽制住了我。"),
    ("They are making movement difficult.", "他們讓移動變得困難。"),
    ("We dare not leave our cover.", "我們不敢離開掩護。"),
    ("We shall do better with more preparation.", "準備更多時，我們會做得更好。"),
    ("No choice but withdrawal.", "別無選擇，只能撤退。"),
    ("Away, quickly.", "離開，快。"),
    ("Vanish like mist.", "如霧般消失。"),
    ("Another time.", "改日再戰。"),
    ("I am well. I hope our other forces can say the same?", "我安然無恙。希望我們其他部隊也能這麼說？"),
    ("I remain unseen.", "我仍未被看見。"),
    ("I am Ronahn.", "我是羅南。"),
    ("What would you have of me?", "你要我做什麼？"),
    ("I am ready.", "我準備好了。"),
    ("You shall not find me unprepared.", "你不會發現我毫無準備。"),
    ("Our eyes are yours to see with.", "我們的眼睛可供你觀看。"),
    ("We are listening.", "我們在聽。"),
    ("On this day we walk in step with you, Farseer.", "今日我們與你步調一致，先知。"),
    ("Observe us if you wish.", "若你願意，就觀察我們。"),
    ("Direct us where you wish.", "按你的意願指引我們。"),
    ("We go or stay at your word.", "去留皆聽你一言。"),
    ("I remain inside a weapon of Vaul.", "我仍在沃爾的武器之內。"),
    ("As ever, the Falcon is ready to hunt.", "一如既往，獵鷹已準備狩獵。"),
    ("Old stories need not be retold.", "舊故事不必重述。"),
    ("Have a care. You are all far from home.", "小心。你們都遠離家園。"),
    ("Ask yourselves who is truly lost.", "問問自己，誰才真正迷失了。"),
    ("I am still Eldar, however long removed from my craftworld.", "無論離開方舟世界多久，我仍是靈族。"),
    ("Who of the Craftworld has the right to judge me?", "方舟世界中誰有權審判我？"),
    ("The land itself offers a tool for our survival.", "這片土地本身提供了求生工具。"),
    ("If we recover this thing, it might prove a great boon.", "若我們回收此物，它或許會成為巨大助益。"),
    ("I have read the battlefield, Farseer. This point is the key.", "我已讀懂戰場，先知。此點就是關鍵。"),
    ("A point of critical strategic import.", "具有關鍵戰略意義的據點。"),
    ("An enemy detachment. I shall learn what I can.", "一支敵方分遣隊。我會盡量查明。"),
    ("I spy enemy activity.", "我偵察到敵人活動。"),
    ("Our foes have a presence here.", "我們的敵人在此有所部署。"),
    ("They have drawn a battle line here.", "他們在此畫下戰線。"),
    ("That weapon could trouble us greatly.", "那件武器可能給我們帶來大麻煩。"),
    ("I have spotted one of their leaders.", "我發現了他們的一名領袖。"),
