    ("They have brought what psychic weaponry they have.", "他們帶來了自己所有的靈能武器。"),
    ("I have found their transport.", "我找到他們的運輸載具。"),
    ("That walker will need swift elimination.", "那台步行機必須迅速消滅。"),
    ("More children of Isha are near.", "更多伊莎之子就在附近。"),
