    ("My fate is not yet sealed.", "我的命運尚未封定。"),
    ("You may call me outcast, but I am Ronahn and I will serve.", "你可以稱我為放逐者，但我是羅南，我會效命。"),
    ("Your Pathfinder is standing by.", "你的尋路者待命中。"),
    ("The Ranger squad stands assembled.", "遊俠小隊已集結。"),
