    ("They can try to catch me.", "他們可以試著抓住我。"),
    ("Must keep moving.", "必須持續移動。"),
    ("Humans. Kill them before they multiply.", "人類。在他們繁殖前殺掉。"),
    ("Were they clever, Orks would be admirable sport.", "若獸人聰明些，他們會是不錯的獵物。"),
