    ("Its debased thought-patterns shall not pollute us.", "它墮落的思維模式不得污染我們。"),
    ("Leave no asylum for the enemy.", "不給敵人留下任何庇護。"),
    ("Reduce them to cinders.", "把他們化為灰燼。"),
    ("Bend it back upon its own path.", "讓它沿自身道路折返。"),
    ("Cripple the other vehicle.", "癱瘓另一輛載具。"),
    ("Pretenders to the mantle of civilization.", "文明外衣的僭稱者。"),
    ("I have a sting of my own.", "我也有自己的毒刺。"),
    ("The hunt has begun.", "狩獵開始了。"),
    ("Ever watchful.", "永遠警惕。"),
    ("I will find their hiding places.", "我會找到他們的藏身處。"),
    ("If I see the foe, I will give it our regards.", "若我看見敵人，我會替我們向它問好。"),
    ("I will kill as I go.", "我會一路殺過去。"),
    ("We have liberty to engage as we see fit.", "我們可按自身判斷自由交戰。"),
    ("Expect the enemy from any direction.", "預期敵人會從任何方向來。"),
    ("Be ready to attack at my word.", "聽我命令準備攻擊。"),
    ("Clear the ground just there.", "清理那片地面。"),
    ("Keep weapons charged.", "保持武器充能。"),
    ("Carry us there against all opposition.", "不顧一切阻力把我們送到那裡。"),
    ("We need a gate here.", "我們需要在此設門。"),
    ("We have a safe path through the Warp.", "我們已有一條穿過亞空間的安全道路。"),
    ("Call forth a weapons platform to greet new visitors.", "喚出武器平台迎接新訪客。"),
    ("The Wraithbone is sung into being.", "幽冥骨在歌聲中成形。"),
    ("I shall claim it.", "我會奪取它。"),
    ("I shall move to seize it.", "我會前去奪取它。"),
    ("An increase in territory.", "領土擴張。"),
    ("We have domain here.", "我們在此取得領域。"),
    ("Yes, we can make use of this device.", "是，我們可以利用這台裝置。"),
    ("It is ours to wield as swiftly as we may.", "它屬於我們，應盡快使用。"),
    ("We shall claim it for the Craftworld.", "我們會為方舟世界奪取它。"),
    ("We have gained valuable ground.", "我們取得了寶貴地盤。"),
    ("Advance and capture Warp Spiders.", "前進並佔領，躍遷蜘蛛。"),
    ("We have achieved our objective.", "我們已達成目標。"),
    ("The predator becomes the prey.", "捕食者變成了獵物。"),
    ("I am brought to bay.", "我被逼入絕境。"),
    ("I have hazarded and lost.", "我冒險了，也輸了。"),
    ("Unexpected.", "出乎意料。"),
    ("I approve.", "我認可。"),
    ("We have served the Craftworld well.", "我們很好地服務了方舟世界。"),
    ("This is not a tale I shall want to tell.", "這不是我想講述的故事。"),
    ("Fate mocks us.", "命運嘲弄我們。"),
    ("None shall stand in our way.", "無人能擋在我們路上。"),
    ("So shall it be, Farseer.", "就這樣吧，先知。"),
    ("It shall be arranged.", "會安排妥當。"),
    ("Elegance of execution.", "執行的優雅。"),
    ("It shall happen.", "它將會發生。"),
    ("To our purpose.", "為了我們的目的。"),
    ("Never fear.", "永不恐懼。"),
    ("I shall make it so.", "我會使其成真。"),
    ("Soon enough.", "很快。"),
    ("I attend to it.", "我會處理。"),
    ("They have not seen all my tricks yet.", "他們還沒見過我所有把戲。"),
    ("My trials nourish me.", "我的試煉滋養了我。"),
    ("I have adapted to my surroundings.", "我已適應環境。"),
    ("The secrets of death.", "死亡的秘密。"),
    ("All guns, open fire.", "所有火炮，開火。"),
    ("Eyes open. One moment of laxity may condemn us all.", "睜大眼睛。片刻鬆懈就可能讓我們全都被定罪。"),
    ("Brothers, in here.", "兄弟們，進這裡。"),
    ("Brothers, relocation on my mark.", "兄弟們，聽我標記轉移。"),
    ("Brothers, push them back.", "兄弟們，把他們推回去。"),
    ("Brothers, show them our fury.", "兄弟們，讓他們見識我們的狂怒。"),
    ("Hurry inside.", "快進去。"),
    ("Search and occupy the building.", "搜索並佔據建築。"),
    ("Load the vehicle quickly.", "迅速登上載具。"),
    ("Come along. We have tasks to tend.", "跟上。我們還有任務要處理。"),
    ("Outside, Warp Spiders.", "出來，躍遷蜘蛛。"),
    ("Take to the ground.", "落到地面。"),
    ("Something has gone awry.", "有些事出錯了。"),
    ("Our control is slipping.", "我們的控制正在滑落。"),
    ("Inexorable disaster.", "無可阻擋的災難。"),
    ("This is insufferable.", "這令人無法忍受。"),
    ("It cannot end this way.", "不能以這種方式結束。"),
    ("No. I refuse.", "不。我拒絕。"),
    ("There is no better proof of life than this.", "沒有比這更好的生命證明。"),
    ("Every nerve sings.", "每一根神經都在歌唱。"),
    ("The glory of the hunt.", "狩獵的榮耀。"),
    ("I must not be weak.", "我不能軟弱。"),
    ("The spider will strike again.", "蜘蛛將再次出擊。"),
    ("The hunt continues.", "狩獵繼續。"),
    ("I must go, the hour wanes.", "我必須走了，時辰將盡。"),
    ("You shall find me there waiting.", "你會發現我在那裡等候。"),
    ("I will go there.", "我會去那裡。"),
    ("I am moving.", "我正在移動。"),
    ("As swiftly as possible.", "盡可能迅速。"),
    ("This will make excellent cover.", "這會成為絕佳掩護。"),
    ("I have come to the place.", "我已來到此地。"),
    ("Let us see what work awaits me.", "讓我們看看有什麼工作等著我。"),
    ("I shall advance our banner.", "我會推進我們的旗幟。"),
    ("I despise turning my back upon an enemy.", "我厭惡背對敵人。"),
    ("Yes, there.", "是，那裡。"),
    ("The time is short and the way is long.", "時間短暫，道路漫長。"),
    ("The journey is underway.", "旅程已經開始。"),
    ("I must not remain in the open.", "我不能留在開闊地。"),
    ("Be wakeful as you go, my brothers.", "前進時保持警醒，我的兄弟們。"),
    ("We are called elsewhere.", "別處在召喚我們。"),
    ("Ignore them. Keep moving.", "無視他們。繼續移動。"),
    ("Quickly now.", "現在，快。"),
    ("Lose no time.", "不要浪費時間。"),
    ("We must be on our way.", "我們必須上路。"),
    ("It is time to go.", "該走了。"),
    ("Find shelter where you can.", "能在哪裡找到掩護就去哪裡。"),
    ("It is too steep a precipice.", "這懸崖太陡。"),
    ("There is no way around.", "沒有路能繞過。"),
    ("I cannot pass the gate except by warp jump.", "除了躍遷跳躍，我無法越過大門。"),
    ("The gate is barred. I could teleport past.", "大門被封住了。我可以傳送過去。"),
    ("The terrain stymies our advance.", "地形阻礙了我們前進。"),
    ("I dislike being cornered.", "我不喜歡被逼入角落。"),
    ("The wall blocks my way. Shall I teleport through?", "牆擋住了我的路。要我傳送過去嗎？"),
    ("A warp jump could take me past this wall.", "一次躍遷跳躍能讓我越過這堵牆。"),
    ("Enemy fire hems us in.", "敵方火力困住了我們。"),
    ("A hail of fire engulfs us!", "火力冰雹吞沒了我們！"),
    ("We must silence their primitive guns.", "我們必須讓他們的原始槍炮沉默。"),
    ("We are trapped behind a blanket of fire.", "我們被困在火網後方。"),
    ("The circumstances are unfavorable.", "情勢不利。"),
    ("We shall prevail by other means.", "我們將以其他手段取勝。"),
    ("Rearward, quickly.", "向後，快。"),
    ("There is a time to give ground.", "有時必須讓出地面。"),
    ("Let them have it -- for now.", "暫時讓給他們。"),
    ("Vanish from here!", "從這裡消失！"),
    ("Any means to the end.", "為達目的，不擇手段。"),
    ("I trust there is purpose to this interruption.", "我相信這次打斷自有目的。"),
    ("Exarch Kaylith prepared.", "大能者凱利斯已準備就緒。"),
    ("Ready to strike at your word.", "聽你命令，準備出擊。"),
    ("No hour here is safe enough for sleep.", "此地沒有任何時辰安全到能夠入睡。"),
    ("Warp Spiders at your command.", "躍遷蜘蛛聽候你的命令。"),
    ("We need only a destination.", "我們只需要目的地。"),
    ("We carry on the battle.", "我們繼續戰鬥。"),
    ("Lost to my Path? Rather, *it* has succumbed to *me*.", "被我的道途吞沒？不如說，是它屈服於我。"),
    ("I embrace my Aspect.", "我擁抱我的戰相。"),
    ("If obsession is a vice, why do we Exarchs lead you?", "若執念是惡習，為何我們大能者會領導你們？"),
    ("Do not fear me. My malignance is only for the foe.", "不要畏懼我。我的惡意只針對敵人。"),
    ("I wonder how they shall try to escape.", "我很好奇他們會如何試著逃跑。"),
    ("It will hurt less if you don't fight.", "若你不反抗，痛苦會少一些。"),
    ("If we study this, it will yield new methods of conquest.", "若研究此物，它會產生新的征服方法。"),
    ("Here is a pretty thing with much to teach us.", "這是一件漂亮東西，有許多可教我們。"),
    ("We could set up an outpost here.", "我們可以在此設置前哨。"),
    ("That point would provide both vantage and dominion.", "那個據點能提供視野與支配。"),
    ("Our foreign kin are here.", "我們的異鄉同族在此。"),
    ("Ah, our people.", "啊，我們的族人。"),
    ("Human drones.", "人類工蜂。"),
    ("Will these hairy animals never die out?", "這些多毛野獸永遠不會滅絕嗎？"),
    ("The Ork blight has spread.", "獸人疫害已經蔓延。"),
    ("Orks in need of extermination.", "需要滅絕的獸人。"),
    ("Behold our prey.", "看，我們的獵物。"),
    ("The foe is in sight.", "敵人在視野內。"),
    ("The enemy stumbles toward my web.", "敵人蹣跚走向我的蛛網。"),
    ("Ah, more challenging prey has arrived.", "啊，更有挑戰的獵物到了。"),
    ("The foe sends mere lackeys abroad.", "敵人只派出嘍囉外出。"),
    ("They have a fascinating pet.", "他們有個迷人的寵物。"),
    ("I have found what passes for their psyker.", "我找到了他們所謂的靈能者。"),
    ("The foe has assigned a vehicle to the area.", "敵人給此區域派了一輛載具。"),
    ("Their walker stalks the land.", "他們的步行機在地上巡行。"),
    ("These moralizing barbarians.", "這些說教的野蠻人。"),
    ("The God-Emperor's sycophants.", "神皇的諂媚者。"),
    ("A Tyranid nest is much too close by.", "泰倫蟲族巢穴離得太近。"),
    ("This place is teeming with Tyranids.", "此地遍布泰倫蟲族。"),
    ("I must consider.", "我必須思考。"),
    ("I desist.", "我暫且停止。"),
    ("Not so hastily.", "別那麼急。"),
    ("Patience.", "耐心。"),
