    ("Our prey forgets its place.", "我們的獵物忘了自己的位置。"),
    ("An opportunity to improve myself.", "提升自我的機會。"),
    ("They have come for me.", "他們來找我了。"),
    ("They are making a thrust.", "他們正在突擊。"),
    ("I must find protection quickly.", "我必須迅速找到防護。"),
