    ("Some loathsome 'magician' assails us.", "某個可憎的「魔術師」正在攻擊我們。"),
    ("They shower us with flame.", "他們向我們灑下火焰。"),
    ("It seeks to run us down.", "它想碾過我們。"),
    ("Their vehicle is seeking us out.", "他們的載具正在尋找我們。"),
    ("The foe beleaguers our tank.", "敵人圍攻我們的坦克。"),
