    ("They battle well for such primitives.", "以原始人而言，他們打得不錯。"),
    ("The gaze of the Hive Mind has fallen on me.", "蟲巢意志的目光落在我身上。"),
    ("The Tyranids seek our blood.", "泰倫蟲族想要我們的血。"),
    ("I rise again, to hunt.", "我再次起身，開始狩獵。"),
    ("My work is not yet done.", "我的工作尚未完成。"),
    ("I am Kaylith of the Warp Spider Temple.", "我是躍遷蜘蛛神殿的凱利斯。"),
    ("The shrine of the Warp Spider Aspect sends me to you.", "躍遷蜘蛛戰相神殿將我派到你身邊。"),
