    ("Let me see what havoc I may wreak with this.", "讓我看看能用它造成何等浩劫。"),
    ("A fine addition to my arsenal.", "我的武庫又添佳品。"),
    ("Our tank suffers damage.", "我們的坦克受損。"),
    ("Our armor is penetrated.", "我們的裝甲被擊穿。"),
    ("The damage is critical.", "損傷嚴重。"),
