    ("Cleanse the monstrosity!", "淨化那怪物！"),
    ("All guns! Open fire!", "所有火炮！開火！"),
    ("Listening post complete.", "監聽站完成。"),
    ("Priority target!", "優先目標！"),
    ("Hunt and destroy. Yes, brother.", "獵殺並摧毀。是，兄弟。"),
    ("It shall be ours.", "它將屬於我們。"),
    ("Death comes to the enemy.", "死亡降臨敵人。"),
    ("Suffer the fate of the heretic.", "承受異端的命運。"),
    ("For Terra and for the Chapter.", "為了泰拉，為了戰團。"),
    ("We bring death to our enemies.", "我們為敵人帶來死亡。"),
    ("Remember your duty: victory or death.", "銘記你的職責：勝利或死亡。"),
    ("My craft is death.", "我的技藝即死亡。"),
    ("There has come a reckoning, Greenskin.", "清算到來了，綠皮。"),
