    ("Remember the Primarchs. They watch us still.", "銘記原體。他們仍在注視我們。"),
    ("Strike true.", "精準打擊。"),
    ("To the last drop of blood.", "直到最後一滴血。"),
    ("Let them feel our fury!", "讓他們感受我們的狂怒！"),
    ("Exercise your faith in combat, brothers.", "在戰鬥中實踐你們的信仰，兄弟們。"),
    ("Feel the might of the righteous.", "感受正義者的威能。"),
    ("I fear nothing for I am fear incarnate.", "我無所畏懼，因我即恐懼化身。"),
