    ("Even in death, I am victorious.", "即便死亡，我亦勝利。"),
    ("Blood for blood.", "以血還血。"),
    ("Never forget. Never forgive.", "永不忘記。永不原諒。"),
    ("I shall fight on.", "我會繼續戰鬥。"),
    ("Let none find us wanting. In His name.", "勿讓任何人認為我們有所欠缺。以祂之名。"),
    ("Alien fiends!", "異族惡魔！"),
    ("Brothers, return fire!", "兄弟們，還擊！"),
    ("Stand firm.", "站穩。"),
    ("Brothers, the Emperor protects.", "兄弟們，帝皇庇佑。"),
    ("Make them pay for this assault!", "讓他們為這次攻擊付出代價！"),
    ("No blow will go unanswered.", "每一次打擊都會得到回應。"),
    ("The time is now, brothers.", "時候到了，兄弟們。"),
    ("Let none find us wanting.", "勿讓任何人認為我們有所欠缺。"),
    ("My faith is my shield. My fury is my sword.", "我的信仰是盾，我的狂怒是劍。"),
    ("We will not bow before these attacks, brothers. We will not!", "我們不會在這些攻擊面前低頭，兄弟們。我們不會！"),
    ("There is only the Emperor; he is our shield and protector.", "唯有帝皇；祂是我們的盾牌與庇護者。"),
