    ("I see forces arrayed against us.", "我看見部隊列陣對抗我們。"),
    ("It is our foe. Shall I remove them?", "那是我們的敵人。要我清除他們嗎？"),
    ("They have come heavily armed.", "他們全副武裝而來。"),
    ("This one has a commanding air.", "這個有指揮者的氣勢。"),
    ("Enemy footsoldiers.", "敵方步兵。"),
    ("A beast, shaped like a warp-daemon.", "一頭形似亞空間惡魔的野獸。"),
    ("It makes a childish attempt to read my mind.", "它幼稚地試圖讀取我的心智。"),
    ("A fast-moving foe.", "快速移動的敵人。"),
    ("It walks, but it has not the grace of my Wraithbone.", "它能行走，卻沒有我的幽冥骨那般優雅。"),
    ("The humans' armored elite are here.", "人類披甲精銳在此。"),
    ("They are twisted by the mind they serve.", "他們被自己侍奉的心智所扭曲。"),
    ("I feel the horror they bring well before I see them.", "在看見他們之前，我已感覺到他們帶來的恐怖。"),
    ("I remain here.", "我留在此處。"),
    ("A respite.", "一段喘息。"),
    ("I await orders.", "我等待命令。"),
    ("I shall stand aside.", "我會退到一旁。"),
    ("I attack only at your word.", "只要你下令，我才攻擊。"),
    ("A halt is called.", "已下令停止。"),
    ("I have rendered you aid.", "我已向你提供援助。"),
    ("That target is no more.", "那個目標不復存在。"),
    ("Their heavy arms shatter.", "他們的重武器粉碎了。"),
    ("Its will was strong, but no more.", "它的意志曾經強大，但如今不再。"),
    ("Their tiny souls fray.", "他們渺小的靈魂正在磨損。"),
    ("I have trampled them underfoot.", "我已將他們踩在腳下。"),
    ("I have butchered the abomination.", "我已屠宰那憎惡之物。"),
    ("Their foolish psyker has met his deserved fate.", "他們愚蠢的靈能者迎來了應得命運。"),
    ("I have razed the enemy structure.", "我已夷平敵方建築。"),
    ("I have crushed the vehicle.", "我已壓碎那輛載具。"),
    ("I have made an end of their stumbling contraption.", "我已終結他們那台踉蹌的破裝置。"),
    ("What they build, I destroy.", "他們建造的，我摧毀。"),
    ("I have laid their building to waste.", "我已將他們的建築化為荒廢。"),
    ("It will chase us no longer.", "它不會再追逐我們。"),
    ("Their vehicle lies devastated.", "他們的載具已徹底毀壞。"),
    ("I feel a storm of attack.", "我感到攻擊風暴。"),
    ("They fire upon me.", "他們朝我開火。"),
    ("They batter upon me.", "他們猛擊我。"),
    ("The enemy's mockery lumbers toward me now.", "敵人那嘲弄之物正笨重地向我走來。"),
    ("Delicate creatures -- but their weapons bite.", "脆弱生物，但他們的武器會咬人。"),
    ("They besiege me, yet I can feel their trepidation.", "他們圍攻我，但我能感到他們的恐懼。"),
    ("Barbaric Orks strike at me.", "野蠻獸人正在攻擊我。"),
    ("It seems this body is not invulnerable.", "看來這具軀體並非無敵。"),
    ("Their blows rain heavy.", "他們的打擊沉重如雨。"),
    ("My Wraithbone cracks.", "我的幽冥骨開裂了。"),
    ("My vision fogs. What assails me?", "我的視野模糊了。什麼在攻擊我？"),
    ("Something besets me, but I cannot see it.", "有東西纏住了我，但我看不見它。"),
    ("I feel hate from an alien mind.", "我感到來自異族心智的憎恨。"),
    ("Their cannonade is firing.", "他們的炮擊正在開火。"),
    ("It pierces my Wraithbone with ease.", "它輕易刺穿我的幽冥骨。"),
    ("It seems that war is their religion, and they wish to make their devotions.", "看來戰爭就是他們的宗教，而他們想要獻上虔敬。"),
    ("These humans do not fear me.", "這些人類不怕我。"),
    ("The swarm is upon me.", "蟲群逼近我了。"),
    ("The horror speaks.", "那恐怖之物在說話。"),
    ("You call me again from afar.", "你又從遠方呼喚我。"),
    ("I will serve the Eldar again.", "我將再次為靈族效命。"),
    ("My service is not yet at its end.", "我的效命尚未結束。"),
    ("Once, my name was Elothan.", "曾經，我名為埃洛桑。"),
    ("Let the living tremble before the Wraithlord.", "讓生者在幽冥領主面前顫抖。"),
    ("This world seems distant, but I walk it again.", "此世似乎遙遠，但我再次行走其上。"),
    ("I shall rain razored death upon the enemy.", "我將向敵人降下剃刀般的死亡。"),
    ("I will wield this lance as though Vaul himself had forged it.", "我會揮使這柄光矛，如同沃爾親手鍛造它。"),
    ("The Wraithbone grows around me.", "幽冥骨在我周圍生長。"),
    ("I have been reshaped for new tasks.", "我已被重塑，以承擔新任務。"),
    ("This body has changed.", "這具軀體已改變。"),
    ("You clothe me in the power of the Eldar.", "你以靈族之力為我披甲。"),
    ("Strange that there is no pain.", "奇怪，竟沒有痛苦。"),
    ("My sight in this world dims.", "我在此世的視野正在黯淡。"),
    ("I cannot move.", "我無法移動。"),
    ("My weapons fail me.", "我的武器辜負了我。"),
    ("No blundering creature shall invade *my* mind.", "沒有笨拙生物能侵入我的心智。"),
    ("Their structure shall fall.", "他們的建築將會倒塌。"),
    ("It is necessary to remove their vehicle.", "必須移除他們的載具。"),
    ("To the end which is bitter.", "走向苦澀的終點。"),
    ("We shall see who dies first.", "我們會看看誰先死。"),
    ("They are still only humans.", "他們終究只是人類。"),
    ("They profane the very name of life.", "他們褻瀆了生命之名。"),
    ("None shall stop us, Farseer.", "無人能阻止我們，先知。"),
    ("Nothing shall deny us.", "沒有什麼能拒絕我們。"),
    ("Weapons drawn.", "武器出鞘。"),
    ("We shall engage as needed.", "我們將按需交戰。"),
    ("Travel light. The foe may be many.", "輕裝前行。敵人或許眾多。"),
    ("The road of the Eldar is long and fraught with peril.", "靈族之路漫長且危機四伏。"),
    ("Another door open into the Webway.", "另一扇通往網道的門開啟。"),
    ("The weapons platform is in place.", "武器平台已就位。"),
    ("What the Bonesingers have prepared we shall receive.", "骨歌者所準備之物，我們將接受。"),
    ("The Bonesong is complete.", "骨歌已完成。"),
    ("Deploy the Wraithbone.", "部署幽冥骨。"),
    ("We shall acquire it.", "我們會取得它。"),
    ("We have succeeded in our objective.", "我們已成功完成目標。"),
    ("Behold our new possession.", "看我們的新所有物。"),
    ("We have it, Farseer.", "我們得到了，先知。"),
    ("We have taken a trophy.", "我們奪得一件戰利品。"),
    ("We cannot fail.", "我們不能失敗。"),
    ("Closing in on the objective.", "正在逼近目標。"),
    ("Consider the territory in our hands.", "將此領土視為已在我們手中。"),
    ("Give it not a moment's thought.", "不必為此多想片刻。"),
    ("We will capture it.", "我們會佔領它。"),
    ("It will serve the Craftworld well.", "它會很好地服務方舟世界。"),
    ("We stand upon newly gained ground.", "我們站在新取得的土地上。"),
    ("Sing the songs of war!", "唱響戰歌！"),
    ("Strike swiftly and true", "迅速而精準地打擊"),
    ("To battle my kin", "投入戰鬥，我的同族"),
    ("They have no hope of survival.", "他們沒有生還希望。"),
    ("We will cut a swath through their ranks.", "我們會在他們隊列中劈開一條血路。"),
    ("Khaine will be pleased with our onslaught", "凱恩會因我們的猛攻而愉悅"),
