    ("Into the fray!", "衝入戰局！"),
    ("You will die by Eldar hands", "你將死於靈族之手"),
    ("Prepare to meet your end", "準備迎接你的終結"),
    ("Why will you not die?", "你為何還不死？"),
    ("Exterminate them", "滅絕他們"),
    ("We must prevail", "我們必須取勝"),
