    ("Stay close. We guard each others' flanks.", "靠近些。我們守護彼此側翼。"),
    ("Now is the time for songs to become deeds.", "現在是讓歌謠化為行動之時。"),
    ("Our armor fails", "我們的裝甲失效"),
    ("Perhaps it is time to give in to hate.", "也許該屈從於仇恨了。"),
    ("We must hold the enemy back!", "我們必須擋住敵人！"),
