    ("Away from me!", "離我遠點！"),
    ("Targeting the Ork.", "正在瞄準獸人。"),
    ("Now, into the Space Marines!", "現在，衝向星際戰士！"),
    ("I shall destroy that platform.", "我會摧毀那座平台。"),
    ("Silence that human gun.", "讓那座人類炮沉默。"),
    ("Destroy that Ork emplacement.", "摧毀那處獸人陣地。"),
    ("I shall purge that obscenity.", "我會淨化那褻瀆之物。"),
