    ("The victory objective is ours.", "勝利目標屬於我們。"),
    ("Come, the Craftworlds need us still.", "來吧，方舟世界仍然需要我們。"),
    ("Your path is not at an end, Eldar.", "靈族，你的道途尚未結束。"),
    ("I still have need of you Ork.", "獸人，我仍然需要你。"),
    ("Rise and slay our foes again, brute.", "起身，再次殺戮我們的敵人，蠻子。"),
