    ("You still have a purpose to serve, Space Marine.", "星際戰士，你仍有目的要完成。"),
    ("You may die once I am done with you. Not before.", "等我用完你，你才可以死。在那之前不行。"),
    ("I shall find enemies for you to feast upon, Tyranid.", "泰倫蟲族，我會為你找些可供吞食的敵人。"),
    ("In position within.", "已在內部就位。"),
    ("I see a resource point.", "我看見一處資源點。"),
    ("I spy allies ahead.", "我看到前方有盟友。"),
