    ("An enemy Techmarine faces me.", "敵方技術軍士面對著我。"),
    ("There: a hostile Ork Warboss.", "那裡：敵方獸人戰爭老大。"),
    ("Our Ork enemy is a Mekboy it seems.", "看來我們的獸人敵人是個技霸。"),
    ("A Kommando opposes us. I see him.", "一名特戰小子在對抗我們。我看見他了。"),
    ("So, our enemy is a Farseer.", "所以，我們的敵人是一名先知。"),
    ("I see another Warlock. One hostile to us.", "我看見另一名術士。一名敵對者。"),
    ("An enemy Warp Spider is before me.", "敵方躍遷蜘蛛就在我面前。"),
