    ("The Ork grotesquerie is no more.", "獸人的怪誕之物已不復存在。"),
    ("Tyranid mines eliminated.", "泰倫蟲族地雷已消滅。"),
    ("The enemy wishes to fight hand to hand and sword to sword.", "敵人想手對手、劍對劍地戰鬥。"),
