    ("That human structure must fall, Banshees.", "那座人類建築必須倒下，女妖們。"),
    ("Topple what the Orks have raised.", "推倒獸人築起之物。"),
    ("Orks among those barrels. Let us teach them of pain.", "獸人在那些桶之間。讓我們教會他們痛苦。"),
    ("To the barrels, Banshees, and Orks to slay!", "去桶那裡，女妖們，那裡有獸人可殺！"),
    ("Orks lurk by that pipe. Slay them.", "獸人潛伏在那根管道旁。殺死他們。"),
    ("Charge the pipe, and slay the Orks.", "衝向管道，殺死獸人。"),
    ("To the brush! Ork victims await!", "去灌木！獸人受害者在等著！"),
    ("Dislodge the Orks from the brush, Banshees!", "把獸人從灌木中趕出來，女妖們！"),
    ("Come, let us rid those stones of their Orks.", "來，讓我們清除那些石頭間的獸人。"),
    ("Engage the Orks in the stones!", "攻擊石頭中的獸人！"),
    ("Orks wait behind those roots for us to bring them death.", "獸人在那些根系後等待我們帶去死亡。"),
    ("Into the roots, and slay the green savages.", "進入根系，殺死綠色野蠻人。"),
