    ("Assail those pipes and the Orkish gunners among them.", "攻擊那些管道與其間的獸人槍手。"),
    ("Ork gunners in the brush! Have at them!", "獸人槍手在灌木中！上吧！"),
    ("Kill the Ork gunner cowering in the brush.", "殺死蜷縮在灌木中的獸人槍手。"),
    ("Into the stones! Silence the Ork suppressor!", "進入石堆！讓獸人壓制手沉默！"),
