    ("Ork heavy gun among the stones! Eliminate it!", "獸人重槍在石堆裡！消滅它！"),
    ("Assail the ruins! The Ork gun there is powerful!", "攻擊廢墟！那裡的獸人槍很強！"),
    ("Heavy Ork gun in the ruins! Eliminate it!", "獸人重槍在廢墟中！消滅它！"),
    ("The path is open, Eldar. Come forth.", "道路已開，靈族。出來吧。"),
    ("Let all blows against us falter.", "讓一切打向我們的攻擊動搖。"),
    ("A shield to protect us all.", "保護我們所有人的護盾。"),
