    ("殺害圖勒連長的毒藥", "正在殺死圖勒連長的毒藥"),
    ("揭露這些樣本或許也可以讓我們中和正在殺死圖勒連長的毒素", "找到這些樣本或許也能讓我們中和正在殺死圖勒連長的毒素"),
    ("生體毒素樣本阻礙了正在殺死圖勒連長的毒素", "生體毒素樣本阻止了正在殺死圖勒連長的毒素"),
    ("擊殺圖勒連長的毒素", "正在殺死圖勒連長的毒素"),
