    ("萊吉斯巢都尖塔", "萊吉斯居住尖塔"),
    ("維尼克圖斯巢都尖塔", "維尼克圖斯居住尖塔"),
    ("阿斯塔特制式", "阿斯塔特制式裝備"),
    ("M40 阿斯塔特制式裝備 - MKIIa", "M40 阿斯塔特制式裝備 - Mk IIa"),
    ("MKVII天鷹裝甲", "Mk VII 天鷹裝甲"),
    ("MKVII 天鷹裝甲", "Mk VII 天鷹裝甲"),
    ("MKVII「天鷹」裝甲", "Mk VII「天鷹」裝甲"),
    ("MKVII指揮官樣式電力補給", "Mk VII 指揮官型動力供應器"),
    ("MKVII 天鷹型式。此重裝裝甲以厚鈦板打造而成，並結合電力光纖束，是星際戰士的特有裝備。", "Mk VII 天鷹型。這套重型裝甲由厚重陶鋼板製成，內嵌電驅纖維束，是星際戰士的標誌性裝備。"),
    ("MKVII 天鷹型號。此重裝裝甲以厚鈦板打造而成，並結合電力光纖束，是星際戰士的特有裝備。", "Mk VII 天鷹型。這套重型裝甲由厚重陶鋼板製成，內嵌電驅纖維束，是星際戰士的標誌性裝備。"),
    ("Mk VII 天鷹型。由厚重陶鋼板與電驅纖維束構成，是星際戰士標誌性的重型裝甲。", "Mk VII 天鷹型。這套重型裝甲由厚重陶鋼板製成，內嵌電驅纖維束，是星際戰士的標誌性裝備。"),
    ("Mk VIII迷途類型。此重裝裝甲以厚陶板打造而成，並結合電力光纖束，是星際戰士的特有裝備。", "Mk VIII 游俠型。這套重型裝甲由厚重陶鋼板製成，內嵌電驅纖維束，是星際戰士的標誌性裝備。"),
    ("MK VIII 迷途類型動力裝甲，裝備額外陶鋼，使其裝備者在戰鬥中精神更充沛。", "Mk VIII 游俠型動力甲，加裝額外陶鋼板，使穿戴者在戰鬥中更能承受打擊。"),
    ("仲裁庭 III 型「執法者」。擁有短距但強大的傷害，戰鬥霰彈槍可以讓滲透的偵察兵小隊靠近敵人開火，可有效打擊步兵。", "仲裁庭 III 型「執法者」。戰鬥霰彈槍射程短但傷害沉重，能讓滲透偵察兵貼近敵人完成擊殺。對步兵有效。"),
    ("仲裁庭 III 型「執法者」。擁有短距但強大的傷害，戰鬥霰彈槍可以讓滲透的偵察兵靠近敵人以完成擊殺，可有效打擊步兵。", "仲裁庭 III 型「執法者」。戰鬥霰彈槍射程短但傷害沉重，能讓滲透偵察兵貼近敵人完成擊殺。對步兵有效。"),
    ("仲裁庭 III 型「執法者」。戰鬥霰彈槍射程較短但傷害沉重，使滲透中的偵察兵能貼近目標完成擊殺。對步兵有效。", "仲裁庭 III 型「執法者」。戰鬥霰彈槍射程短但傷害沉重，能讓滲透偵察兵貼近敵人完成擊殺。對步兵有效。"),
    ("Alt+X 會強制你所有單位撤退至總部。", "Alt+X 會命令你所有單位撤退至總部。"),
    ("EMP 力場 - 將其他護盾無人機和其半徑內所有敵人鎖定在 EMP 力場中。受 EMP 力場影響的敵人與無人機無法受到傷害、移動或攻擊。", "EMP 力場 - 將其他護盾無人機及其半徑內所有敵人鎖定在 EMP 力場中。受 EMP 力場影響的敵人與無人機無法受到傷害、移動或攻擊。"),
    ("先進無人機控制器會向區域內所有護盾無人機發送信號，命令立即進行 EMP 鎖定。EMP 力場會影響護盾下的所有敵人與護盾無人機。受 EMP 力場影響的單位暫時無法移動、受到傷害或攻擊。", "先進無人機控制器會向區域內所有護盾無人機發送信號，命令立即執行 EMP 鎖定。EMP 力場會影響護盾範圍內的所有敵人與護盾無人機。受 EMP 力場影響的單位暫時無法移動、受到傷害或攻擊。"),
    ("Mk VII 天鷹型。這套重型裝甲由厚重陶鋼板製成，內嵌電動纖維束，是星際戰士的典型特徵。", "Mk VII 天鷹型。這套重型裝甲由厚重陶鋼板製成，內嵌電驅纖維束，是星際戰士的標誌性裝備。"),
    ("在它遺失之前，MKVII 動力裝甲曾在血鴉第三連的鐵血試煉中展示，以終可證明自身價值的象徵激勵希望。", "失落之前，這套 Mk VII 動力甲曾在血鴉第三連舉行的鐵血試煉中展出，以未來可能成就的象徵激勵志願者，只要他們能證明自身價值。"),
    ("不給迷途者憐憫。", "誤入歧途者不得憐憫。"),
    ("給我們迷途的兄弟讓路。", "給我們誤入歧途的兄弟讓路。"),
    ("M36配發，瑪格那核心樣式", "M36 配發型，三重冗餘「瑪格那核心」型"),
    ("M36模式，瑪格那核心樣式", "M36 配發型，三重冗餘「瑪格那核心」型"),
    ("MKXa - 分裂樣式", "Mk Xa「撕裂」型"),
    ("M38樣式 - 緊急出血彈", "M38 配發型 - 緊急止血線圈"),
    ("電力此設備以獲得額外的能量資源。", "建造此設備以獲得額外的電力資源。"),
    ("阿斯塔特MKV 導彈發射器 ，裝載著高爆導彈匣。這個武器用來對付那些自以為躲在裝甲後方很安全的敵人。可有效對付載具和建築。", "阿斯塔特 Mk V 導彈發射器，裝填高爆穿甲導彈，專門懲治那些自以為躲在裝甲板後便安全的敵人。對載具與建築有效。"),
    ("阿斯塔特 MKIIs 型狙擊步槍，射程遠但射速較慢。這款平衡精良的狙擊步槍適合遠程處理重要目標，對步兵有效。", "阿斯塔特 Mk IIs 型狙擊步槍，射程遠但射速較慢。這款平衡精良的步槍擅長從遠距離消滅高價值目標。對單體步兵有效。"),
    ("阿斯塔特 MKIII，此隨身攜帶武器讓星際戰士可同時裝備近戰武器，以在近戰時發揮造成重大傷害。", "阿斯塔特 Mk III。這把副武器讓裝備近戰武器的星際戰士在接近近戰前仍可造成傷害。"),
    ("基本款.998古德溫樣式爆彈槍。裝備自行推進的高爆尖彈匣，每把爆彈槍皆為手工打造且受到火星技術神甫的祝福，是效忠帝皇之星際戰士的標準配件。", "標準配發 .998 古德溫型爆彈槍。發射自推進高爆彈，每把爆彈槍都由手工打造，並受火星技術神甫祝福，是帝皇麾下星際戰士的標誌性武器。"),
    ("MKX「地獄之牙」鏈鋸劍，是阿斯塔特修會所使用的近戰武器之一，超薄的刀刃可以砍過多數目標，其輪廓則是帝國的徽記。可有效對抗步兵和輕裝甲敵人。", "Mk X「地獄之牙」鏈鋸劍。鏈鋸劍是阿斯塔特修會偏好的近戰武器，單分子齒刃能切開多數目標，其輪廓也是帝國的象徵。對步兵與輕裝甲敵人有效。"),
    ("MKX「地獄之牙」鏈鋸劍，是阿斯塔特修會所使用的近戰武器之一，超薄的刀刃可以砍多數目標，其標誌則是帝國的徽記。可有效對抗步兵和輕裝甲敵人。", "Mk X「地獄之牙」鏈鋸劍。鏈鋸劍是阿斯塔特修會偏好的近戰武器，單分子齒刃能切開多數目標，其輪廓也是帝國的象徵。對步兵與輕裝甲敵人有效。"),
    ("M35瑪格那核心樣式。這支專精武器的射速比爆彈槍還慢，但可以對任何類型目標造成傷害。可有效對抗極重要的單一步兵和載具。", "M35 瑪格那核心型。這件專用配發武器射速慢於爆彈槍，但能傷害任何類型目標。對高價值單體步兵與載具有效。"),
    ("改良的MK XI-c「地獄之牙」鏈鋸劍，擁有相當重量的刀套與相稱的刀柄，使得裝備者能以靈敏的身手揮舞這把劍，進行矛或鎚般的力量攻擊。", "改良型 Mk XI-c「地獄之牙」鏈鋸劍，護手加重，握柄內置配重，使其仍保有劍的靈活，同時能打出如錘杖般沉重的力量。"),
    ("神器動力斧的能量力場完全彌補了混沌星際戰士 MK VI 叛變樣式動力裝甲模組的耐力。", "工匠級動力斧，其能量力場經特殊調校，可配合 MK VI「荷魯斯之亂」型動力甲的容差；這種型號仍是多數混沌星際戰士動力甲的基礎。"),
    ("黑色聖殿星際戰士著名的靈能者憎恨偶爾會延伸到血鴉。傳說此仇恨於M36一場聖殿聖戰中，遭遇由指揮官與智庫所帶領的第五戰團打擊巡洋艦開始。有些人表示，此動力拳套之後明確地被命名是為了刺激聖殿。", "黑色聖堂星際戰士對靈能者的傳奇憎恨，有時也會延伸到血鴉。傳說這份敵意在 M36 達到頂點，當時一支聖堂遠征軍與由指揮官和智庫率領的第五連打擊巡洋艦交戰。有人說，這隻動力拳套後來被刻意命名，就是為了刺激黑色聖堂。"),
    ("洛葛·唐恩是建造防禦工事的大師，也是防禦上著名的戰場指揮官。被創造時，此裝甲被視為是個人防護的傑作，並為基因原體的帝國之拳星際戰士命名。", "羅格·多恩是構築防禦工事的大師，也是防禦作戰的傳奇戰場指揮官。這套裝甲誕生時被視為個人防護的傑作，並以帝國之拳星際戰士的基因原體命名。"),
    ("塔希思奧特戰鬥後，蟲巢艦隊利維坦持續狂暴前進，觸鬚深入星系遙遠的另一端。極限戰士稍後進行了一場絕望的最後抵抗，蟲群見到血鴉打擊巡洋艦進入軌道並部署空投艙時大感訝異。被困在兩支部隊之間，異族野獸被擊退。這套動力裝甲帶著祝福與對抗異族的聖怒連禱被贈與血鴉。", "塔西斯·奧特拉戰役後，蟲巢艦隊利維坦繼續肆虐，觸鬚伸向更遙遠的星系。後來極限戰士面對蟲群苦守最後陣地時，驚訝地看見一艘血鴉打擊巡洋艦進入軌道並投下空投艙。異形野獸被兩面夾擊，最終遭到擊敗。這套動力甲連同祝福與對抗泰倫蟲族的聖怒連禱一併贈予血鴉。"),
    ("在血鴉泰西歐思從死亡守衛的任務中返回後，於服務審判庭期間建立一些功績，並又因為擔任深紅之拳星際戰士和他無盡的勇氣而立下功勞。此強大動力拳套是為了榮耀該戰團而打造。", "血鴉泰瑞西歐斯結束死亡守望服役返回後，很少談及自己效力審判庭時的事蹟。但他曾提起一位深紅之拳星際戰士，以及他無盡的勇氣。這隻強大的動力拳套正是為榮耀該戰團而鍛造。"),
    ("「覬覦的不是斗篷的力量，對我們而言，所要努力的是終身服侍帝皇，且不追求名聲。對我們而言，只有永恆的戰爭，而且我們享受證明我們自身價值的機會。」-- 摘錄自沙杜爾牧師教訓。", "「不要追求強者的披風，因為我們永遠受束於對帝皇的服役，亦不追求聲名。對我們而言，唯有永恆戰爭，而我們樂於把握機會證明自己配得上祂的尊重。」-- 摘自沙杜爾牧師教誨。"),
    ("「他的狡猾是顯而易見的。我們被賦予平定小暴動的任務，但現在我們卻遭遇毀滅整個帝國營地的危險基因竊取者。死亡守衛戰鬥修士的動力拳再次印證了怪獸的末路，將他的頭骨擊成粉末。」--此精緻動力拳套的爆裂能量重擊帝皇敵人。", "「那污穢存在的惡臭幾乎有形。我們原本奉命淨化一場小規模叛亂，卻面對一頭吞噬了整座星界軍營地的兇殘基因竊取者。我的死亡守望戰鬥兄弟用動力拳終結了那頭污獸，伴隨令人滿意的碎裂聲砸塌了它的頭骨。」這隻大師打造的動力拳套迸發能量，用以痛擊帝皇之敵。"),
    ("阿斯塔特MKVb", "阿斯塔特 Mk Vb"),
    ("MKXa - 「撕裂」樣式", "Mk Xa「撕裂」型"),
    ("阿斯塔特MK III。此隨身攜帶武器讓星際戰士可同時裝備近身武器，以在近戰時造成重大傷害。", "阿斯塔特 Mk III。這把副武器讓裝備近戰武器的星際戰士在接近近戰前仍可造成傷害。"),
    ("阿斯塔特MK IVa。威力強大，射速驚人，能壓制並擊殺所有敵軍步兵。可有效對抗多數目標與輕裝甲單位。", "阿斯塔特 Mk IVa 重型爆彈槍。威力強大且射速驚人，能壓制並擊殺敵方步兵。對多數目標與輕裝甲單位有效。"),
    ("阿斯塔特MK IIs有著遠程但射速緩慢的火力，這種完美平衡的狙擊步槍適合於遠程對付重要目標。可有效對抗單一步兵。", "阿斯塔特 Mk IIs 型狙擊步槍，射程遠但射速較慢。這款平衡精良的步槍擅長從遠距離消滅高價值目標。對單體步兵有效。"),
    ("阿斯塔特MK IVe重型爆彈槍裝填改造爆彈槍子彈，可在目標前方引爆，局部爆炸可掃蕩敵軍步兵。", "阿斯塔特 Mk IVe 重型爆彈槍裝填改造爆彈，會在目標前方引爆，以局部爆炸掃蕩敵方步兵。"),
    ("阿斯塔特MK IVc重型爆彈槍，擁有大師級穩定器裝配，使裝備者具高度抗力，而不易被擊退。", "阿斯塔特 Mk IVc 重型爆彈槍配有大師級穩定器，使使用者更能抵抗擊退。"),
    ("阿斯塔特MK II阿比西尼亞樣式，此衝鋒炮是能有效進行壓制的武器。不同於重型爆彈槍，它同時也可有效對抗裝甲載具，同時讓另一手可使用動力拳套。", "阿斯塔特 Mk II「阿比西尼亞」型突擊炮。這件武器能有效壓制敵人；不同於重型爆彈槍，它也能有效對抗裝甲載具，並讓另一手仍可使用動力拳套。"),
    ("阿斯塔特Mk IIIt爆彈手槍經過改造後可發射地獄火毒霧子彈，對抗異形特別有效。槍管旁飾有藥劑師的服務誓言。", "阿斯塔特 Mk IIIt 爆彈手槍經改造後可發射地獄火毒霧彈，對異形尤其有效。槍管側面刻有藥劑師的服役誓言。"),
    ("M40 阿斯塔特配發 - MKIIa", "M40 阿斯塔特制式裝備 - Mk IIa"),
    ("阿斯塔特 MKVb", "阿斯塔特 Mk Vb"),
    ("黑色聖殿", "黑色聖堂"),
    ("死亡守衛戰鬥修士", "死亡守望戰鬥兄弟"),
    ("死亡守衛的任務", "死亡守望的任務"),
    ("擔任死亡守衛", "效力死亡守望"),
    ("動力裝甲", "動力甲"),
