    ("樣式霰彈槍", "型霰彈槍"),
    ("仲裁庭 MK IX 霰彈槍", "仲裁庭 Mk IX 霰彈槍"),
    ("斬殺者型霰彈槍", "殺戮者型霰彈槍"),
    ("樣式", "型"),
    ("最初獻給異族審判庭作為對抗異族的證據，許多死亡守衛星際戰士利用這把鏈鋸刀屠殺人類的敵人。當第一個使用該能力的血鴉泰圖思兄弟返回塔爾塔羅斯，且死於對抗靈族後，審判庭為了向他表示敬意而將這把劍送給戰團。", "這把鏈刃最初由異形審判庭祝聖，作為對抗異形的憑證；許多死亡守望星際戰士曾用它斬殺人類之敵。第一位以此身份服役的血鴉泰瑞索斯兄弟返回塔爾塔羅斯，並在對抗靈族時戰死後，審判庭為紀念他而將此劍贈予戰團。"),
    ("泰西歐思，第一位曾經在審判庭擔任異族獵殺死亡守衛的血鴉，開始服役時便是帶著這把等離子手槍。從此之後，它陪伴了所有血鴉執行類似的任務。", "泰瑞西歐斯是第一位加入審判庭異形獵殺組織死亡守望的血鴉。他開始服役時帶上了這把等離子手槍。此後，它陪伴每一位執行同類任務的血鴉。"),
    ("軍士布林成為第二位效勞於審判庭死亡守衛的戰團兄弟後，血鴉戰團軍械庫便將此重型爆彈槍交付給他。當它返回軍械庫時，不僅見證了許多戰爭的恐怖，也獲得了三名審訊者的祝福", "布林軍士成為第二位效力審判庭死亡守望的血鴉兄弟時，戰團軍械庫將這把重型爆彈槍託付給他。它回到軍械庫時，已見證過大量殘酷戰鬥，並獲得三名審判官的祝福。"),
    ("死亡守衛賽勒斯", "死亡守望的賽勒斯"),
    ("賽勒斯於死亡守衛服役了將近兩個世紀。雖然他的非正統的戰術一直被其他的血鴉同袍視為古怪，但他們完全支持他。", "賽勒斯曾在死亡守望服役近兩個世紀。他那些非正統戰術在血鴉同袍眼中一直顯得古怪，卻被死亡守望的小隊戰友完全接納。"),
    ("賽勒斯於維多利亞保瑪士之戰後，結束了死亡守衛的職務，並決定帶著所學的技能帶回血鴉。", "賽勒斯在維多利亞·普萊穆斯戰役後結束死亡守望服役，並決心把所學全部帶回血鴉。"),
    ("賽勒斯軍士偏愛微妙且不落俗套的戰略，而這些戰略卻總是受到他的星際戰士同伴嗤之以鼻。然而，同樣的這些戰術確認他贏得死亡守衛的注意。", "賽勒斯軍士偏愛微妙且非常規的戰術，這些戰術並不總受星際戰士同伴歡迎。然而，正是這些戰術讓他受到死亡守望的注意；死亡守望是為帝國審判庭效力的精英異形獵殺部隊。"),
    ("賦予死亡守衛青睞的疫病戰士，這些致命武器獲得受詛咒軍團的基因原體莫卡安祝福。", "這些致命武器賜予死亡守衛中備受青睞的疫病戰士，並獲得受詛咒軍團的惡魔基因原體莫塔里安祝福。"),
