    ("保護能源節點，並可以建造電力發電機。", "鞏固能源節點，並允許建造電力發電機。"),
    ("防禦電力發電機", "防守電力發電機"),
    ("提升電力資源率", "提升電力資源獲取率"),
    ("如果敵人佔領了控制你電力發電機的戰略點，那麼該發電廠將會落入敵人手中，並增加他們的電力來源。", "如果敵人佔領了控制你電力發電機的戰略點，這些發電機就會落入敵人手中，並提高他們的電力收入。"),
    ("透過啟動的能源節點興建電力發電機。", "啟動能源節點後，即可建造電力發電機。"),
    ("機械之神儀式可以修復載具、電力發電機與狼蛛哨戒槍。", "機械神儀式可在戰場上修復載具、電力發電機與狼蛛哨戒炮。"),
