    ("重型爆彈槍槍座", "重型爆彈炮塔"),
    ("架設一具狼蛛哨戒炮在目標地點，重型爆彈炮塔可以有效傷害和壓制敵人步兵", "在目標位置部署一座狼蛛哨戒炮。重型爆彈炮塔可有效傷害並壓制敵方步兵。"),
    ("我們造成了大量傷害，但我們在你的命令下部署額外的狼蛛哨戒炮。", "我們已造成大量傷害，但仍可按你的命令部署額外的狼蛛哨戒炮。"),
    ("指揮官，我已經補滿狼蛛哨戒炮。", "指揮官，狼蛛哨戒炮已重新補給完畢。"),
    ("定位儀是一種自動導向裝置，讓我們可以發射狼蛛哨戒炮至您指定的地點。", "定位儀是一種自動導向裝置，可讓我們將狼蛛哨戒炮部署到你指定的位置。"),
    ("將你的狼蛛哨戒炮塔放置於牆壁後方以確保它們的安全，這些裝置很容易被敵方的遠程炮火摧毀，將它們放在牆後至少可以減少一些可能遭到的彈擊。", "把狼蛛哨戒炮放在牆後以確保安全。這些裝置很容易被敵方遠程火力摧毀，放在牆後至少能減少部分炮火威脅。"),
    ("利用定位儀精準部署狼蛛哨戒炮。這些重型爆彈炮塔可以有效傷害與壓制敵軍步兵。", "利用定位儀精準部署狼蛛哨戒炮。重型爆彈炮塔可有效傷害並壓制敵方步兵。"),
    ("利用定位儀精準部署狼蛛哨戒炮。這些重型爆彈炮塔可以有效傷害並壓制敵軍步兵部隊。", "利用定位儀精準部署狼蛛哨戒炮。重型爆彈炮塔可有效傷害並壓制敵方步兵。"),
    ("在指定位置部署一狼蛛哨戒炮。重型爆彈炮塔可以有效傷害並壓制敵軍步兵部隊。", "在指定位置部署一座狼蛛哨戒炮。重型爆彈炮塔可有效傷害並壓制敵方步兵。"),
    ("在指定位置部署一狼蛛哨戒炮。重型爆彈炮塔可以有效傷害並壓制敵軍步兵部隊。", "在指定位置部署一座狼蛛哨戒炮。重型爆彈炮塔可有效傷害並壓制敵方步兵。"),
    ("狼蛛哨戒砲", "狼蛛哨戒炮"),
    ("重型爆彈槍塔", "重型爆彈炮塔"),
    ("在指定位置部署一狼蛛哨戒炮。重型爆彈炮塔可以有效傷害並壓制敵軍步兵部隊。", "在指定位置部署一座狼蛛哨戒炮。重型爆彈炮塔可有效傷害並壓制敵方步兵。"),
    ("你是%1COMMANDERNAME%，一名剛晉升為指揮官的星際戰士。", "你是 %1COMMANDERNAME%，一名最近晉升為部隊指揮官的星際戰士。"),
    ("你是 %1COMMANDERNAME%，一名最近晉升為戰士長的星際戰士。", "你是 %1COMMANDERNAME%，一名最近晉升為部隊指揮官的星際戰士。"),
    ("%1COMMANDER%晉升為指揮官，因為他率領一支小隊深入敵後殲滅一支拖延戰役的強大炮兵中隊，並成功奪回海德里安星球。", "%1COMMANDER% 率領一支小隊深入敵後，摧毀了阻礙奪回哈德良星球戰役的大型炮兵陣地，並因此晉升為部隊指揮官。"),
    ("%1COMMANDER% 率領一支小隊深入敵後，摧毀了阻礙奪回哈德良星球戰役的龐大炮兵陣地，並因此晉升為戰士長。", "%1COMMANDER% 率領一支小隊深入敵後，摧毀了阻礙奪回哈德良星球戰役的大型炮兵陣地，並因此晉升為部隊指揮官。"),
    ("%1COMMANDER%是血鴉最年輕的指揮官，戰團裡許多人驚訝於%1COMMANDER%的勇氣，但也有人認為他的晉升過於草率。", "%1COMMANDER% 是有史以來最年輕的血鴉部隊指揮官。戰團中許多人對 %1COMMANDER% 的武勇印象深刻，但也有人認為這次晉升過於倉促。"),
    ("%1COMMANDER% 是有史以來最年輕的血鴉戰士長。戰團中許多人對 %1COMMANDER% 的武勇印象深刻，但也有人認為這次晉升過於倉促。", "%1COMMANDER% 是有史以來最年輕的血鴉部隊指揮官。戰團中許多人對 %1COMMANDER% 的武勇印象深刻，但也有人認為這次晉升過於倉促。"),
    ("事實上，%1COMMANDER%有能力摧毀炮兵中隊，並將整個小隊毫髮無傷地帶回，因此被認為幾乎是個奇蹟。", "%1COMMANDER% 能夠摧毀炮兵陣地，並讓整支小隊毫髮無傷地返回，這件事被認為簡直就是奇蹟。"),
    ("雖然戰團長親自下達晉升命令，但卻受到相當大的反抗，因為戰團長未曾見過%1COMMANDER%本人。", "這次晉升由戰團長本人下令，並在巨大阻力面前仍然維持生效，儘管戰團長其實從未親眼見過 %1COMMANDER%。"),
    ("軍階%1LEVEL% - %2CLASS%", "軍隊等級 %1LEVEL% - %2CLASS%"),
    ("%1COMMANDER%曾經從阿米吉多頓號打擊巡洋艦率領他的星際戰士。", "%1COMMANDER% 曾經從阿米吉多頓號打擊巡洋艦上率領他的星際戰士。"),
    ("指揮官%1COMMANDER%和他的星際戰士目前效力於天譴打擊巡洋艦，支援血鴉第三連隊的艦隊之一。", "指揮官 %1COMMANDER% 和他的星際戰士如今服役於懲戒號打擊巡洋艦，該艦隸屬於支援血鴉第三連的艦隊。"),
    ("指揮官%1COMMANDER%和他的星際戰士如今服役於懲戒號打擊巡洋艦，該艦隸屬於支援血鴉第三連的艦隊。", "指揮官 %1COMMANDER% 和他的星際戰士如今服役於懲戒號打擊巡洋艦，該艦隸屬於支援血鴉第三連的艦隊。"),
    ("泰倫蟲族入侵期間，馬特勒斯與指揮官%1COMMANDER%並肩作戰。", "泰倫蟲族入侵期間，馬特勒斯與指揮官 %1COMMANDER% 並肩作戰。"),
