    ("指揮傳送背包；允許戰士長穿越亞空間重新定位，無需正面突擊接近敵人。", "指揮傳送背包；允許部隊指揮官穿越亞空間重新定位，無需正面突擊接近敵人。"),
    ("賦予戰士長與附近盟友對遠程火力的抗性及壓制免疫。", "賦予部隊指揮官與附近盟友對遠程火力的抗性及壓制免疫。"),
