    ("戰士長", "部隊指揮官"),
    ("這支重型爆彈槍是為黑暗天使的基因原體里昂．艾爾強森所鑄造，充滿著他對於賀拉斯再起的狂怒。", "這把重型爆彈槍為紀念黑暗天使基因原體萊昂·艾爾莊森而鍛造，據說會吐出他對荷魯斯之亂中背叛行徑的怒火。"),
    ("包圍著奔馳的能量，這個Mark IIc動力拳套曾經附屬於血鴉英雄泰圖思的終結者甲。該套件在戰團手上遺失，但此拳套仍持續對人類的敵人施予懲戒之力。", "奔流能量環繞著這隻 Mk IIc 動力拳套。它曾裝配在血鴉英雄泰瑞索斯的終結者甲上。那套戰甲已為戰團所失，但這隻拳套仍會將他的懲戒降於人類之敵。"),
    ("泰圖思連長之墓", "泰瑞索斯連長之墓"),
    ("與塔爾塔羅斯交戰結束後一年，技術軍士布萊尼率領攻擊部隊回到毀滅的世界，以取回赫諾盧思·泰圖思的上古聖物。儘管受到嚴重傷害，這名偉大的步行機甲依然挺立在血鴉被迫離開的地方。它回到戰團軍火庫是件非常值得慶祝的事情。", "塔爾塔羅斯戰事結束一年後，技術軍士布倫南率領打擊部隊返回那個荒蕪世界，尋回殞落者霍諾留斯·泰瑞索斯的聖物。儘管遭受重創，這台偉大的無畏機甲仍挺立在血鴉被迫棄置它的地方。它回到戰團軍械庫，成為值得隆重慶祝之事。"),
    ("泰圖思之手", "泰瑞索斯之手"),
    ("當赫諾盧思·泰圖思這位血鴉第三連隊的無畏機甲在塔爾塔羅斯戰役中死亡時，許多步行機甲迷失在戰鬥的混亂狀態中。儘管如此，這個古老且強大的爪透過技術軍士布萊尼回到戰團軍械庫。", "當血鴉第三連無畏機甲霍諾留斯·泰瑞索斯在塔爾塔羅斯迎來終結時，機體大部分都遺失於戰鬥的混亂中。儘管如此，這隻古老而強大的爪仍由技術軍士布倫南帶回戰團軍械庫。"),
    ("泰圖思連長的一片神聖無畏機甲碎片被鑄造至此終結者甲，結果連長的不死狂怒注入至裝備者身上，使他們可以持續著最兇暴的攻擊行動。", "泰瑞索斯連長神聖無畏機甲的一塊碎片被鑄入這套終結者甲。因此，連長不滅的狂怒會顯現於穿戴者身上，使其足以承受最猛烈的攻擊。"),
    ("大聖戰最終因為被稱為賀拉斯再起的這場內戰叛徒而挫敗。篡位者雖被阻撓，但帝皇在最終戰役中因為他背信棄義的兒子赫魯斯身受重傷，現在只能藉由黃金王座的科技維持生命。", "大遠征最終被內部叛亂所阻，這場大內戰被稱為荷魯斯之亂。篡位者被擊敗，但帝皇在最終決戰中被叛逆之子荷魯斯重創，如今只能依靠黃金王座的科技維持生命。"),
    ("由帝國之拳專屬的鍛造大師所打造並贈與血鴉，以感謝他們在布瑞爾聖戰期間的鼎力相助。此不屈不撓的裝甲紀念著帝國之拳於賀拉斯再起期間對抗鋼鐵戰士的可怕戰鬥。", "這套不屈裝甲由帝國之拳的鍛造大師親手打造，並贈予血鴉，以感謝他們在布里爾聖戰期間的援助。它紀念帝國之拳在荷魯斯之亂期間對抗鋼鐵勇士的慘烈戰鬥。"),
    ("殺了他們獻給飛蟲領主。", "殺了他們，獻給蠅王。"),
    ("自從賀拉斯再起之後，此武器每年都要奪取一條性命，且並非全都是人類的敵人。", "自荷魯斯之亂以來，這件武器每年都會奪走一條性命，而且並非全都屬於人類之敵。"),
    ("在戰團最受尊崇的神器中，賀拉斯叛變最高潮時，此華麗的裝甲據信曾在星界軍登上賀拉斯的戰艦時被帝皇的警衛所裝備。", "在戰團最受尊崇的神器中，這套華麗裝甲據信曾由帝皇衛士穿戴；荷魯斯之亂最高潮時，他們登上了荷魯斯的戰鬥駁船「復仇之魂」。"),
