    ("艾沙鐸", "伊薩多"),
    ("偉大的加百列·安傑洛斯據說在對抗伊薩多·阿基奧斯的戰鬥中背負著此戰旗，戰旗因此成了血鴉逆轉勝的勝利象徵。", "據說偉大的加百列·安傑洛斯曾在對抗伊薩多·阿基奧斯的戰鬥中背負這面戰旗。因此，這面戰旗成為血鴉扭轉戰局、奪取勝利的象徵。"),
    ("血鴉加百列·安傑洛斯連長利用此手槍擊殺曾經是他的密友，叛徒伊薩多·阿基奧斯。安傑洛斯因厭惡毀滅之力與他們帶給人類的墮落而丟棄這把槍。他的戰鬥修士找到此武器，並將它帶回戰團軍械庫。", "血鴉連長加百列·安傑洛斯曾用這把手槍殺死叛徒伊薩多·阿基奧斯，後者曾是他最親密的朋友。安傑洛斯厭惡毀滅之力及其帶給人類的污穢，於是丟棄此槍。他的戰鬥兄弟找回武器，並將其送回血鴉軍械庫。"),
    ("雙手雷霆錘是血鴉軍械庫裡最強大的近戰武器，只有指揮官可以使用，可以傷害所有目標，但卻妨礙了遠程武器的使用。", "雙手雷霆錘是血鴉軍械庫中最強大的近戰武器。只有部隊指揮官能使用，這件動力武器可以傷害所有目標。不過，它也會排除使用任何遠程武器的可能。"),
    ("如同毀滅之力渴望著它。", "正如毀滅之力渴望著它。"),
