    ("超級重裝步兵", "重型步兵"),
    ("此遺物爆彈槍上刻有貞潔與對受混沌引誘者的責難印記。", "這把遺物爆彈槍刻有純潔印記，以及對受混沌誘惑者的譴責銘文。"),
    ("我打倒了一個戰鎚!", "俺要把錘子砸下來！"),
    ("我打倒了一個戰鎚！", "俺要把錘子砸下來！"),
    ("哇，那些蟲子有熔化玩意！", "哇，那些蟲子有熱熔玩意兒！"),
    ("哇，那些蟲子有熔化玩意兒！", "哇，那些蟲子有熱熔玩意兒！"),
    ("丟出熱熔炸彈，爆炸效果可以消滅載具或更大目標，造成大量傷害並讓目標短時間無法移動。", "投擲一枚熱熔炸彈，這種炸藥能有效摧毀載具或其他大型目標。造成高額傷害並暫時固定目標。"),
    ("丟出熱熔炸彈，爆炸效果可以消滅載具或更大目標，造成大量傷害並讓目標移動緩慢。", "投擲一枚熱熔炸彈，這種炸藥能有效摧毀載具或其他大型目標。造成高額傷害並暫時減速目標。"),
    ("突擊小隊取得了熱熔炸彈及閃光彈的技巧", "賦予突擊小隊熱熔炸彈和致盲手雷能力"),
    ("閃光手雷投出！", "致盲手雷已投出！"),
    ("閃光手雷投出。", "致盲手雷已投出。"),
    ("閃光彈包", "致盲手雷包"),
    ("閃光彈可以短暫的使敵方部隊無法行動，防止敵方移動或攻擊。", "致盲手雷可短暫震懾敵方單位，使其無法移動或開火。"),
    ("閃光彈", "致盲手雷"),
    ("閃光手雷", "致盲手雷"),
    ("為突擊小隊裝備熱熔炸彈（有效打擊載具）與致盲手雷（有效打擊建築中的部隊）。", "為突擊小隊配備熱熔炸彈（擅長對抗載具）與致盲手雷（對建築內單位有效）。"),
    ("開啟熱熔炸彈和致盲手雷", "解鎖熱熔炸彈與致盲手雷"),
    ("裝備短距離的跳躍背包。額外升級包含了致盲手雷及熱熔炸彈。", "配備跳躍背包，擅長迅速拉近距離。額外升級包括致盲手雷與熱熔炸彈。"),
    ("手雷額外的字到這", "手雷額外文字在此"),
    ("手榴彈額註解在此", "手雷額外文字在此"),
    ("手雷額註解在此", "手雷額外文字在此"),
    ("對潘西精靈沒有幫助。", "那些娘娘腔尖耳朵沒救了。"),
    ("沒有討人厭的蜘蛛精在一旁，我們的防衛會更安全。", "不必再擔心精英躍遷蜘蛛後，我們的防禦安全得多。"),
    ("我聞到了排骨精靈族。", "俺聞到瘦巴巴靈族的味兒了。"),
    ("點擊完成以離開精靈。", "點擊「完成」以離開安裝精靈。"),
    ("矮人褐", "矮人青銅"),
    ("矮人橘", "矮人膚色"),
    ("精靈橘", "精靈膚色"),
    ("蟲巢暴君要召喚防衛部隊了，快趁機開火。", "蟲巢暴君正在召喚護衛，開火！"),
    ("不是戰爭，防衛部隊，不是。但我們參與的部分結束了。", "不是整場戰爭，星界軍士兵，不是。但我們參與的部分已經結束了。"),
    ("防衛部隊擋住敵人了", "星界軍士兵正在擋住敵人。"),
    ("還有更多防衛部隊，快去支援他們", "還有更多星界軍士兵。快去支援他們。"),
    ("別慌張，防衛部隊，炮台和迫擊砲可以把他們炸個精光", "別慌，星界軍士兵。炮台和迫擊炮會把他們炸個粉碎。"),
    ("防衛部隊，撤回前線基地並檢查傷勢。", "星界軍士兵，撤回前線基地並照看傷員。"),
    ("蟲群側面包圍他們的主要戰線，而且阻斷了防衛部隊。", "蟲群已從側翼包抄他們的主防線，並切斷了星界軍士兵。"),
    ("那些仍在熔爐的防衛部隊人手嚴重不足。", "仍在熔爐中的那些星界軍士兵人手嚴重不足。"),
    ("進入天使之門並協助剩餘的防衛部隊。", "進入天使之門，協助剩餘的星界軍士兵。"),
    ("放下你的武器，防衛部隊。", "放下你的武器，星界軍士兵。"),
    ("背叛者防衛部隊，我才正打算問候他們呢。", "叛變星界軍。我才剛開始尊重他們。"),
    ("報告，防衛部隊。", "報告情況，星界軍士兵。"),
    ("那些防衛部隊指望著我們！我們讓他們失望了！", "那些星界軍士兵指望著我們！我們讓他們失望了！"),
    ("那些防衛部隊再次涉入。", "那些星界軍士兵又陷入苦戰了。"),
    ("防衛部隊？他們在這裡做什麼？", "星界軍士兵？他們在這裡做什麼？"),
    ("沒有任何忠誠的防衛部隊會對星際戰士開火。", "沒有任何忠誠的星界軍士兵會向星際戰士開火。"),
    ("這些防衛部隊投入不少心力設置這個陷阱。", "這些星界軍士兵為這個陷阱投入了不少心力。"),
    ("可能是衛隊裝備，不過這些不是防衛部隊，他們是背叛者。", "也許是星界軍裝備，但這些人不是忠誠的星界軍士兵。他們是叛徒。"),
    ("那些防衛部隊已經為背叛帝皇付出了代價。", "那些星界軍士兵已為背叛帝皇付出代價。"),
    ("防衛部隊稱這地方為加百列的奇蹟。", "星界軍士兵稱這地方為加百列的奇蹟。"),
    ("德羅莎脆弱的防衛部隊現在可以毫無畏懼地前進了。", "德羅莎麾下脆弱的星界軍士兵現在可以毫無畏懼地前進了。"),
    ("血鴉第一戰團的老兵達摩尼司在克羅努斯聖戰期間使用此重型火焰噴射器。他毫不遲疑地使用此武器對付勝利灣的防衛部隊叛徒和混沌異端。", "血鴉第一連老兵達摩尼司在克羅努斯聖戰期間使用過這把重型火焰噴射器。他毫不遲疑地用它焚燒勝利灣的叛變星界軍與混沌異端。"),
    ("當提供天使之門動力的發電機無法運作時，塔普政委召集了第85護衛軍團的防衛部隊徒勞地試圖阻止異形蜂擁而至。", "當為天使之門供能的發電機停擺時，塔普政委集結第85文多蘭星界軍團的士兵，徒勞地試圖阻止異形蜂擁而至。"),
    ("叛逆防衛部隊", "叛變星界軍"),
